Here is the commit message:
ASoC: Intel: avs: Set name of control as in topology
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

When creating controls attached to widgets, there are a lot of rules if
they get their name prefixed with widget name or not. Due to that
controls ended up with weirdly looking names like "ssp0_fe DSP Volume",
while topology set it to "DSP Volume".

Fix this by setting no_wname_in_kcontrol_name to true in avs topology
widgets which disables unwanted behaviour.

Fixes: be2b81b519d7 ("ASoC: Intel: avs: Parse control tuples")
Signed-off-by: Amadeusz Sławiński <amadeuszx.slawinski@linux.intel.com>
Link: https://lore.kernel.org/r/20240418142621.2487478-1-amadeuszx.slawinski@linux.intel.com
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The bug was caused by the naming convention applied to controls attached to widgets, where the widget name was being prefixed to the control names, resulting in undesirably formatted names like "ssp0_fe DSP Volume" instead of the intended names defined in the topology, such as "DSP Volume". This behavior was due to the default setting of the `no_wname_in_kcontrol_name` property being false, which led to the unwanted prefixing.

Here is the patch:

 static int avs_widget_load(struct snd_soc_component *comp, int index,
 			   struct snd_soc_dapm_widget *w,
 			   struct snd_soc_tplg_dapm_widget *dw)
 {
 	struct snd_soc_acpi_mach *mach;
 	struct avs_tplg_path_template *template;
 	struct avs_soc_component *acomp = to_avs_soc_component(comp);
 	struct avs_tplg *tplg;
 	int ssp_port, tdm_slot;

 	if (!le32_to_cpu(dw->priv.size))
 		return 0;

+	w->no_wname_in_kcontrol_name = true;
+
 	if (w->ignore_suspend && !AVS_S0IX_SUPPORTED) {
 		dev_info_once(comp->dev, "Device does not support S0IX, check BIOS settings\n");
 		w->ignore_suspend = false;
 	}

 	tplg = acomp->tplg;
 	mach = dev_get_platdata(comp->card->dev);
 	if (!avs_mach_singular_ssp(mach))
 		goto static_name;
 	ssp_port = avs_mach_ssp_port(mach);

 	/* See parse_link_formatted_string() for dynamic naming when(s). */
 	if (avs_mach_singular_tdm(mach, ssp_port)) {
 		/* size is based on possible %d -> SSP:TDM, where SSP and TDM < 10 + '\0' */
 		size_t size = strlen(dw->name) + 2;
 		char *buf;

 		tdm_slot = avs_mach_ssp_tdm(mach, ssp_port);

 		buf = kmalloc(size, GFP_KERNEL);
 		if (!buf)
 			return -ENOMEM;
 		avs_ssp_sprint(buf, size, dw->name, ssp_port, tdm_slot);
 		kfree(w->name);
 		/* w->name is freed later by soc_tplg_dapm_widget_create() */
 		w->name = buf;
 	}

 static_name:
 	template = avs_tplg_path_template_create(comp, tplg, dw->priv.array,
 						 le32_to_cpu(dw->priv.size));
 	if (IS_ERR(template)) {
 		dev_err(comp->dev, "widget %s load failed: %ld\n", dw->name,
 			PTR_ERR(template));
 		return PTR_ERR(template);
 	}

 	w->priv = template; /* link path information to widget */
 	list_add_tail(&template->node, &tplg->path_tmpl_list);
 	return 0;
 }



